<?php
declare(strict_types=1);
require_once __DIR__ . '/business/config/role_portal_auth.php';
$error=null;$csrf='';
try{
    $pdo=role_portal_db();role_portal_ensure($pdo);security_step17_session_start();
    if(security_step17_total_users($pdo)===0){header('Location: business/setup_admin.php');exit;}
    $existing=security_step17_session_user($pdo,false);
    if($existing){header('Location: '.((int)$existing['must_change_password']===1?'change_password.php?required=1':role_portal_home($existing)));exit;}
    $csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));
        $user=security_step17_login($pdo,(string)($_POST['email']??''),(string)($_POST['password']??''));
        header('Location: '.((int)$user['must_change_password']===1?'change_password.php?required=1':role_portal_home($user)));exit;
    }
}catch(Throwable $e){$error=$e->getMessage();}
